package de.local.tapoviewer;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;
import org.junit.runner.RunWith;
import org.json.*;
import java.util.*;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class ExpansionDeviceTest {
    private Context isolated;private CameraRepository repo;
    @Before public void setup(){Context target=InstrumentationRegistry.getInstrumentation().getTargetContext();isolated=new ContextWrapper(target){public Context getApplicationContext(){return this;}public SharedPreferences getSharedPreferences(String name,int mode){return target.getSharedPreferences("expansion_test_"+name,mode);}};isolated.getSharedPreferences("camera_configuration",0).edit().clear().commit();repo=new CameraRepository(isolated);}
    @After public void clean(){isolated.getSharedPreferences("camera_configuration",0).edit().clear().commit();}
    @Test public void newSettingsPagesOpenAndRenderOnTv()throws Exception{android.app.Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();Context target=instrumentation.getTargetContext();for(Class<?> type:new Class<?>[]{AppSettingsActivity.class,ViewsActivity.class,BackupActivity.class}){android.app.Activity screen=instrumentation.startActivitySync(new Intent(target,type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));instrumentation.waitForIdleSync();try{instrumentation.runOnMainSync(()->{android.view.View root=screen.getWindow().getDecorView();assertTrue(root.getWidth()>0);assertTrue(root.getHeight()>0);android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(root.getWidth(),root.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);root.draw(new android.graphics.Canvas(bitmap));try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(target.getCacheDir(),"expansion-"+type.getSimpleName()+".png"))){assertTrue(bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out));}catch(Exception e){throw new RuntimeException(e);}finally{bitmap.recycle();}});}finally{instrumentation.runOnMainSync(screen::finish);instrumentation.waitForIdleSync();}}}
    @Test public void restoresPortableAccountsAndMergesWithoutDeletingOtherCameras()throws Exception{
        Camera c=new Camera("192.0.2.10","Portable");repo.upsert(c);SecureCredentialsStore store=new SecureCredentialsStore(isolated);store.save(c.id,"backup-test-user","backup-test-password");store.saveSecret(c.id+"_url","rtsp://192.0.2.10/main?token=test-token");repo.saveView("Portable view",Collections.singletonList(c.id),2,false);repo.setOption("auto_delete","true");
        JSONObject withAccounts=new JSONObject(BackupData.export(isolated,true));JSONObject noAccounts=new JSONObject(BackupData.export(isolated,false));assertFalse(noAccounts.getJSONArray("accounts").getJSONObject(0).has("pass"));
        Context destination=new ContextWrapper(isolated){public Context getApplicationContext(){return this;}public SharedPreferences getSharedPreferences(String name,int mode){return isolated.getSharedPreferences("restored_"+name,mode);}};
        try{CameraRepository restored=new CameraRepository(destination);restored.upsert(new Camera("192.0.2.11","Keep"));BackupData.restore(destination,withAccounts);assertEquals(2,restored.loadCameras().size());assertEquals("backup-test-user",new SecureCredentialsStore(destination).load(c.id).username);assertEquals("backup-test-password",new SecureCredentialsStore(destination).load(c.id).password);assertTrue(restored.find(c.id).playbackUrl.contains("test-token"));assertEquals(1,restored.views().length());assertEquals("false",restored.option("auto_delete","true"));}
        finally{store.remove(c.id);destination.getSharedPreferences("secure_camera_settings",0).edit().clear().commit();destination.getSharedPreferences("camera_configuration",0).edit().clear().commit();}
    }
    @Test public void persistsCameraPoliciesViewsOrderingAndPositions()throws Exception{Camera a=new Camera("192.0.2.1","A"),b=new Camera("192.0.2.2","B"),c=new Camera("192.0.2.3","C");a.gridStream=1;a.fullStream=2;a.aspectMode=1;a.muted=false;a.volume=30;repo.saveCameras(Arrays.asList(a,b,c));Camera copy=repo.find(a.id);assertEquals(1,copy.gridStream);assertEquals(2,copy.fullStream);assertFalse(copy.muted);assertEquals(30,copy.volume);repo.move(c.id,-1);assertEquals(c.id,repo.loadCameras().get(1).id);repo.saveView("Outside",Arrays.asList(c.id,a.id),-2,false);repo.selectView("Outside");assertEquals(-2,repo.getTileCount());assertEquals(c.id,repo.liveCameras().get(0).id);assertEquals(2,repo.liveCameras().size());c.enabled=false;repo.upsert(c);assertEquals(1,repo.liveCameras().size());repo.saveNamedViewport(a.id,"Gate",2,-.4f,.7f);repo.saveNamedViewport(a.id,"Door",3,.2f,-.1f);assertEquals(2,repo.positions(a.id).length());assertEquals(3,repo.loadViewport(a.id).zoomIndex);assertEquals(0,repo.positions(b.id).length());}
    @Test public void backupEncryptionAndValidationWorkOnReceiver()throws Exception{Camera c=new Camera("192.0.2.1","Test");repo.upsert(c);JSONObject backup=new JSONObject();backup.put("version",1);backup.put("settings",new JSONObject(repo.settingsJson()));backup.put("accounts",new JSONArray().put(new JSONObject().put("id",c.id)));BackupActivity.validate(backup);byte[] bytes=BackupCodec.encrypt(backup.toString(),"receiver-test-password".toCharArray());assertEquals(backup.toString(),BackupCodec.decrypt(bytes,"receiver-test-password".toCharArray()));backup.getJSONArray("accounts").getJSONObject(0).put("id","unknown");try{BackupActivity.validate(backup);fail();}catch(IllegalArgumentException expected){}}
}
